row_click_today.customFunction:
setTimeout(function() {
    const ts = parseInt(localStorage.getItem('riego_ts'));

    const start = new Date(ts);
    start.setHours(0, 0, 0, 0);

    const end = new Date(ts);
    end.setDate(end.getDate() + 1);
    end.setHours(0, 0, 1, 0);

    widgetContext.dashboard.onUpdateTimewindow(start.getTime(), end.getTime());
}, 500);

row_click.customFunction:
const stateId = 'caudalimetro_detalle'; // tu id real
const stateParams = {
    entityId: { id: entityId.id, entityType: entityId.entityType },
    entityName: entityName
};
widgetContext.stateController.openState(stateId, stateParams, false);

setTimeout(function() {
    const ts = parseInt(localStorage.getItem('riego_ts'));

    const start = new Date(ts);
    start.setHours(0, 0, 0, 0);

    const end = new Date(ts);
    end.setDate(end.getDate() + 1);
    end.setHours(0, 0, 1, 0);

    widgetContext.dashboard.onUpdateTimewindow(start.getTime(), end.getTime());
}, 500);

tooltip.patternFunction:
let soil_hum_1 = data.soil_hum_1;
let soil_hum_2 = data.soil_hum_2;
let soil_hum_3 = data.soil_hum_3;
let soil_ce_4 = data.soil_ce_4;
let soil_temp_5 = data.soil_temp_5;
let ExtTemp = data.ExtTemp;
let ExtHum = data.ExtHum;
let rain_1 = data.rain_1;
let solar_radiation_1 = data.solar_radiation_1;
let wind_speed_2 = data.wind_speed_2;
let wind_direction_3 = data.wind_direction_3;
let irrigation_1_1 = data.irrigation_1_1;
let battery = data.battery;

let nombre = data.entityName.replace("Nodo_", "Sensor ");
let html = "<b>" + nombre + "</b><br><br>";

function hasValue(v) {
    return v !== null && v !== undefined && v !== '' && !isNaN(Number(v));
}

if (hasValue(soil_hum_1)) html += `<b>Humedad 15 cm:</b> ${Number(soil_hum_1).toFixed(1)} %<br>`;
if (hasValue(soil_hum_2)) html += `<b>Humedad 30 cm:</b> ${Number(soil_hum_2).toFixed(1)} %<br>`;
if (hasValue(soil_hum_3)) html += `<b>Humedad 45 cm:</b> ${Number(soil_hum_3).toFixed(1)} %<br>`;

if (hasValue(soil_ce_4)) html += `<b>Conductividad:</b> ${Number(soil_ce_4).toFixed(2)}<br>`;
if (hasValue(soil_temp_5)) html += `<b>Temp. suelo:</b> ${Number(soil_temp_5).toFixed(1)} °C<br>`;

if (hasValue(ExtTemp)) html += `<b>Temp. ambiente:</b> ${Number(ExtTemp).toFixed(1)} °C<br>`;
if (hasValue(ExtHum)) html += `<b>Humedad ambiente:</b> ${Number(ExtHum).toFixed(1)} %<br>`;

if (hasValue(rain_1)) html += `<b>Lluvia:</b> ${Number(rain_1)} mm<br>`;
if (hasValue(solar_radiation_1)) html += `<b>Radiación solar:</b> ${Number(solar_radiation_1)} W/m²<br>`;

if (hasValue(wind_speed_2)) html += `<b>Viento:</b> ${Number(wind_speed_2)} km/h<br>`;
if (hasValue(wind_direction_3)) html += `<b>Dirección:</b> ${Number(wind_direction_3)}°<br>`;

if (irrigation_1_1 !== null && irrigation_1_1 !== undefined && irrigation_1_1 !== '') {
    html += `<b>Riego:</b> ${Number(irrigation_1_1)}<br>`;
    
}
// if (irrigation_1_1 !== null && irrigation_1_1 !== undefined && irrigation_1_1 !== '') {
//     let riego = Number(irrigation_1_1);

//     if (riego === 0) {
//         html += `<b>Riego:</b> Inactivo<br>`;
//     } else if (riego === 1) {
//         html += `<b>Riego:</b> Activo<br>`;
//     } else {
//         html += `<b>Riego:</b> ${riego}<br>`;
//     }
// }

if (hasValue(battery)) {
    let batteryValue = Number(battery);

    if (batteryValue > 100) {
        html += `<b>Batería:</b> ${batteryValue.toFixed(0)} mV<br>`;
    } else {
        html += `<b>Batería:</b> ${batteryValue.toFixed(1)} %<br>`;
    }
}

html += "<br><link-act name='ver_tuberiaP'>Ver Información de la Estación</link-act>";

return html;

