settings.cardCss:
.menu-card{
    font-family:'Mulish', sans-serif;
    width:100%;
    height:100%;
    background:white;
    border-radius:8px;
    box-shadow:0 2px 8px rgba(0,0,0,.15);
    display:flex;
    flex-direction:column;
    align-items:center;
    justify-content:center;
    padding:12px;
    box-sizing:border-box;
    overflow:hidden;
    cursor:pointer;
    transition:transform .2s ease, box-shadow .2s ease;
}
.menu-card:hover{
    transform:translateY(-4px);
    box-shadow:0 8px 20px rgba(0,0,0,.22);
}
.menu-card:hover .icon-circle{
    background:#5F8FC4;
}
.menu-card:hover .icon-circle svg{
    color:#ffffff;
}
.icon-circle{
    width:30%;
    min-width:40px;
    max-width:90px;
    height:0;
    padding-bottom:30%;
    min-height:40px;
    max-height:90px;
    flex-shrink:0;
    border-radius:50%;
    background: #E9F0F8;
    position:relative;
    margin-bottom:10px;
}
.icon-circle svg{
    color:#5F8FC4;
    position:absolute;
    top:50%;
    left:50%;
    transform:translate(-50%,-50%);
    width:55%;
    height:55%;
}
.card-title{
    text-align:center;
    font-family:'Playfair Display', serif;
    font-size:13px;
    font-weight:700;
    color: #3F3530;
    margin-bottom:10px;
    white-space:normal;
    overflow-wrap:normal;
    word-break:normal;
    line-height:1.25;
    max-width:100%;
}
@media (min-width:900px){
    .card-title{ font-size:16px; }
}
@media (min-width:1200px){
    .card-title{ font-size:20px; }
}
@media (min-width:1700px){
    .card-title{ font-size:26px; }
}
.card-description{
    text-align:center;
    color: #786F68;
    line-height:1.6;
    font-size:16px;
    flex:1;
}
.card-footer{
    width:100%;
    display:flex;
    justify-content:space-between;
    align-items:center;
    margin-top:15px;
    font-size:18px;
    color: #3F3530;
}
.arrow{
    color: #5F8FC4;
    font-size:28px;
}
.menu-card{position:relative;}
.menu-card::after{content:'';position:absolute;left:14px;right:14px;bottom:0;height:3px;background:#5F8FC4;border-radius:3px 3px 0 0;}

