headerButton.customFunction:
var tsActualStr = localStorage.getItem('riego_ts');
var tsActual = tsActualStr ? parseInt(tsActualStr) : new Date().getTime();
var fechaActual = new Date(tsActual);
var tsAyer = new Date(fechaActual.getFullYear(), fechaActual.getMonth(), fechaActual.getDate() - 1, 0, 0, 0).getTime();

// Ocultar panel actual para que la transición sea limpia
var $miPanel = $(widgetContext.$container).closest('.cdk-overlay-pane');
var $miBackdrop = $('.cdk-overlay-backdrop');
$miPanel.attr('data-iay-oculto', '1').css({ visibility: 'hidden', pointerEvents: 'none' });
$miBackdrop.attr('data-iay-oculto', '1').css({ visibility: 'hidden', pointerEvents: 'none' });

// 1. Guardar la variable normal de toda la vida
localStorage.setItem('riego_ts', tsAyer.toString());

// 2. EL SECRETO DESCUBIERTO EN date-rangue.json
// Empaquetamos la fecha exactamente con el formato JSON que exige el otro widget
var paquete = {
    ts: tsAyer,
    creado: Date.now()
};
localStorage.setItem('riego_ts_ir_ayer', JSON.stringify(paquete));

// 3. Buscar la acción nativa oculta (,m) y abrir el popup
var descriptores = widgetContext.actionsApi.getActionDescriptors('headerButton');
var descNavegar = descriptores.find(function(d) { return d.type === 'openDashboardState'; });

if (descNavegar) {
    widgetContext.actionsApi.handleWidgetAction($event, descNavegar, entityId, entityName);
} else {
    console.error('[Ir a ayer] No se encontró la acción oculta (,m).');
}

// 4. Limpieza del panel fantasma
var intentos = 0;
function comprobarSiAyerSeCerro() {
    intentos++;
    var quedanVisibles = $('.cdk-overlay-pane').not('[data-iay-oculto]').length;
    if (quedanVisibles === 0) {
        var $botonCerrar = $miPanel.find('button').filter(function() {
            return $(this).find('mat-icon').text().toLowerCase() === 'close';
        });
        if ($botonCerrar.length > 0) $botonCerrar.get(0).click();
        return;
    }
    if (intentos < 720) window.setTimeout(comprobarSiAyerSeCerro, 5000);
}
window.setTimeout(comprobarSiAyerSeCerro, 5000);

